    if not isinstance(mutex_raw, list) or not isinstance(requires_raw, list):
        raise ValueError("rules values must be lists")

    index = {key: i for i, key in enumerate(keys)}
    costs: list[Decimal] = []
    gains: list[Decimal] = []
    for key in keys:
