import json

import urban_micro as um

assert "panel_priority" in um.__all__


def attr(pairs, n=2):
    parts = []
    for key, expected, reject in pairs:
        parts.append(
            '{"key":' + json.dumps(key)
            + f',"n":{n},"expected":{expected:.6f},"worst":{expected:.6f}'
            + ',"sensitivity":0.000000,"p":1.000000,"q":1.000000,"reject":'
            + ("true" if reject else "false")
            + "}"
        )
    return (
        '{"alpha":1.000000,"total_weight":2.000000,"items":['
        + ",".join(parts)
        + "]}\n"
    )


# Two panels under the same region (r1), windows w1 and w2.
p1 = attr([("a", 4.0, True), ("b", 2.0, True), ("c", 1.0, False)])
p2 = attr([("a", 0.0, False), ("b", 0.0, True), ("c", 0.0, False)])
reports = {("r1", "w2"): p1, ("r1", "w1"): p2}
weights = {("r1", "w2"): 1, ("r1", "w1"): 1}
cost = {"a": 3, "b": 2, "c": 1}

# Reference panel_report at alpha=1: every group rejects (q=1 <= 1).
rep = json.loads(um.panel_report(reports, weights, alpha=1.0))
by = {(g["by"], g["key"]): g["items"] for g in rep["groups"]}
overall = {it["key"]: it for it in by[("overall", "all")]}

out = um.panel_priority(reports, weights, cost, 3, alpha=1.0)
print(out)
data = json.loads(out)
assert list(data) == ["alpha", "limit", "cost", "score", "pick", "items"]
# all candidates significant at alpha=1 -> pick = max score under budget 3.
# overall means: a=2, b=1, c=0.5; stable = min over 3 groups:
# region r1 (== overall here): stable = [0.5,1,0]; window w1 p2-only, w2 p1-only.
items = {it["key"]: it for it in data["items"]}
for it in data["items"]:
    assert list(it) == [
        "key", "cost", "score", "stable", "significant", "rank", "pick"
    ]
    assert isinstance(it["rank"], int)
    assert isinstance(it["significant"], bool)
    assert isinstance(it["pick"], bool)
# score check
from decimal import Decimal
for key in "abc":
    stab = min(
        g_items[key]["stable"] for g_items in (
            {i["key"]: i for i in g["items"]} for g in rep["groups"]
        )
    )
    assert items[key]["stable"] == stab
    expected_score = round(overall[key]["mean"] * stab, 6)
    assert items[key]["score"] == expected_score, (key, items[key]["score"])
# rank order: score desc -> a (1.0), b (1.0), c (0)
assert [it["key"] for it in data["items"]] == ["a", "b", "c"]
assert [it["rank"] for it in data["items"]] == [1, 2, 3]
# budget 3: 'a' alone costs 3 score 1; 'b'+'c' costs 3 score 1 -> tie,
# smaller lexicographic key list: ('a',) vs ('b','c') -> 'a' wins.
assert data["pick"] == ["a"]
assert data["cost"] == 3.0
assert data["score"] == 1.0
assert out.endswith("\n") and not out.endswith("\n\n")
assert " " not in out.rstrip("\n")

# alpha tiny -> nothing significant -> empty pick, zero totals
out2 = um.panel_priority(reports, weights, cost, 3, alpha=0.000001)
d2 = json.loads(out2)
assert d2["pick"] == []
assert d2["cost"] == 0.0
assert d2["score"] == 0.0
assert all(not it["pick"] for it in d2["items"])
assert all(not it["significant"] for it in d2["items"])

# error semantics
for bad in ([], None, 7):
    try:
        um.panel_priority(bad, weights, cost, 3)
    except TypeError:
        pass
    else:
        raise AssertionError("reports TypeError")
    try:
        um.panel_priority(reports, bad, cost, 3)
    except TypeError:
        pass
    else:
        raise AssertionError("weights TypeError")
    try:
        um.panel_priority(reports, weights, bad, 3)
    except TypeError:
        pass
    else:
        raise AssertionError("cost TypeError")

try:
    um.panel_priority(reports, weights, {"a": 3, "b": 2}, 3)
except ValueError:
    pass
else:
    raise AssertionError("cost keys ValueError")

try:
    um.panel_priority(reports, weights, {"a": -1, "b": 2, "c": 1}, 3)
except ValueError:
    pass
else:
    raise AssertionError("positive cost ValueError")

try:
    um.panel_priority(reports, weights, {"a": True, "b": 2, "c": 1}, 3)
except ValueError:
    pass
else:
    raise AssertionError("bool cost ValueError")

try:
    um.panel_priority(reports, weights, cost, -0.1)
except ValueError:
    pass
else:
    raise AssertionError("negative limit ValueError")

# bool limit/alpha -> ValueError (reports/weights dicts first)
try:
    um.panel_priority(reports, weights, cost, True)
except ValueError:
    pass
else:
    raise AssertionError("bool limit ValueError")

# panel_report still behaves identically
r = um.panel_report(reports, weights, alpha=1.0)
assert r.endswith("\n")
assert r == rep and False or isinstance(r, str)
print("ALL OK")

